'use strict';
const $=id=>document.getElementById(id), MINUTE=60000,API='https://api.bitget.com/api/v2/',COLORS=['#bbf96b','#60d6c5','#9b9bff'];
let results=[],history=[],busy=false,scanned=0,failures=0,total=0,eligible=0,limit=20,target=0,lastAttempt=0,direction='long',windowMinutes=5,snapshot=0,mode='breakout',selectedSymbol='';
try{history=JSON.parse(localStorage.getItem('pulse-breakout-history-v1')||'[]');if(!Array.isArray(history))history=[]}catch{history=[]}
const num=(n,d=2)=>Number(n).toLocaleString('de-DE',{maximumFractionDigits:d,minimumFractionDigits:d});
const pct=n=>Number.isFinite(n)?(n>=0?'+':'')+num(n)+'%':'—';
const price=n=>Number.isFinite(n)?n.toLocaleString('de-DE',{maximumSignificantDigits:7}):'—';
const compact=n=>Number.isFinite(n)?new Intl.NumberFormat('de-DE',{notation:'compact',maximumFractionDigits:2}).format(n):'—';
const time=t=>new Date(t).toLocaleTimeString('de-DE',{timeZone:'UTC',hour:'2-digit',minute:'2-digit'});
const interval=(end,n=windowMinutes)=>time(end-n*MINUTE)+'–'+time(end);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tone=n=>n>=0?'positive':'negative';
const numeric=v=>v===null||v===undefined||v===''?NaN:Number(v);
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const url=r=>'https://www.bitget.com/futures/usdt/'+encodeURIComponent(r.symbol);
function patternOptions(){return {minutes:+$('candle-size').value,pullbackBars:+$('pullback-count').value,minImpulse:+$('impulse-min').value,minVolume:+$('impulse-volume').value,maxRetracement:+$('max-retrace').value,requireQuiet:$('quiet-pullback').value==='yes'}}
function getSetup(r){return (r.setups||[]).find(s=>s.side===direction&&($('setup-status').value==='all'||s.status===$('setup-status').value))}
function recomputePatterns(){const opts=patternOptions();results.forEach(r=>r.setups=PulsePattern.detect(r.candles,target,opts))}
const ranked=()=>mode==='setup'?results.filter(r=>getSetup(r)).sort((a,b)=>{const sa=getSetup(a),sb=getSetup(b);return (sb.status==='confirmed')-(sa.status==='confirmed')||sb.volumeRatio-sa.volumeRatio||Math.abs(sb.impulsePct)-Math.abs(sa.impulsePct)}):results.filter(r=>Number.isFinite(r.returns[windowMinutes])&&(direction==='long'?r.returns[windowMinutes]>0:r.returns[windowMinutes]<0)).sort((a,b)=>(direction==='long'?b.returns[windowMinutes]-a.returns[windowMinutes]:a.returns[windowMinutes]-b.returns[windowMinutes])||b.dayVolume-a.dayVolume);

let nextRequest=0;
async function api(path,retries=1,root=API){const slot=Math.max(Date.now(),nextRequest);nextRequest=slot+125;await sleep(Math.max(0,slot-Date.now()));const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const res=await fetch(root+path,{signal:controller.signal,cache:'no-store'});if(!res.ok)throw Error('HTTP '+res.status);const json=await res.json();if(json.code!=='00000'||!Array.isArray(json.data))throw Error(json.msg||'Ungültige API-Antwort');return json.data}catch(e){if(retries){await sleep(700);return api(path,retries-1,root)}throw e}finally{clearTimeout(timer)}}
function windowData(candles,end,n){const byTime=new Map(candles.map(c=>[+c[0],c])),selected=[];for(let t=end-n*MINUTE;t<end;t+=MINUTE){const c=byTime.get(t);if(!c||!(+c[1]>0)||!(+c[4]>0)||!Number.isFinite(+c[6]))return null;selected.push(c)}return {change:(+selected.at(-1)[4]/+selected[0][1]-1)*100,volume:selected.reduce((s,c)=>s+ +c[6],0)}}
function metrics(t,contract){const bid=numeric(t.bidPr),ask=numeric(t.askPr),mid=(bid+ask)/2;return {last:numeric(t.lastPr),day:numeric(t.change24h)*100,dayVolume:numeric(t.quoteVolume),spread:bid>0&&ask>=bid?(ask-bid)/mid*100:NaN,funding:numeric(t.fundingRate)*100,fundInterval:contract.fundInterval||'?',oi:numeric(t.holdingAmount)}}
function spark(values,color=COLORS[0]){if(values.length<2)return '';const lo=Math.min(...values),range=Math.max(...values)-lo||1;return `<svg viewBox="0 0 240 60" preserveAspectRatio="none" aria-label="Kursverlauf" role="img"><path d="${values.map((v,i)=>(i?'L':'M')+(i/(values.length-1)*240).toFixed(2)+','+(52-(v-lo)/range*44).toFixed(2)).join(' ')}" fill="none" stroke="${color}" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>`}
function momentumChart(){const top=ranked().slice(0,3);if(!top.length)return;const maps=top.map(r=>new Map(r.candles.slice(-60).map(c=>[+c[0],+c[4]])));const common=[...maps[0].keys()].filter(t=>maps.every(m=>m.has(t))).sort((a,b)=>a-b);if(common.length<2){$('chart').className='chart-empty';$('chart').textContent='Zu wenig gemeinsame Kursdaten für einen Vergleich.';return}
 const series=maps.map(m=>common.map(t=>(m.get(t)/m.get(common[0])-1)*100));let lo=Math.min(0,...series.flat()),hi=Math.max(0,...series.flat());if(hi===lo){lo-=.1;hi+=.1}const pad=(hi-lo)*.12;lo-=pad;hi+=pad;const x=i=>42+i/(common.length-1)*616,y=v=>12+(hi-v)/(hi-lo)*180;
 let svg='<svg viewBox="0 0 680 220" role="img" aria-label="Normierte Kursentwicklung der Top 3 über bis zu 60 Minuten">';for(let i=0;i<5;i++){let v=lo+(hi-lo)*i/4;svg+=`<line x1="42" x2="658" y1="${y(v)}" y2="${y(v)}" stroke="#27343b" stroke-dasharray="3 5"/><text x="0" y="${y(v)+3}" fill="#71858f" font-size="9">${num(v,1)}%</text>`}
 series.forEach((s,i)=>{svg+=`<path d="${s.map((v,j)=>(j?'L':'M')+x(j).toFixed(2)+','+y(v).toFixed(2)).join(' ')}" fill="none" stroke="${COLORS[i]}" stroke-width="2.2"/>`});[0,Math.floor((common.length-1)/2),common.length-1].forEach(i=>svg+=`<text x="${x(i)}" y="215" text-anchor="middle" fill="#71858f" font-size="9">${time(common[i]+MINUTE)}</text>`);$('chart').className='chart';$('chart').innerHTML=svg+'</svg>';$('legend').innerHTML=top.map((r,i)=>`<span><i style="background:${COLORS[i]}"></i>${esc(r.base)}</span>`).join('');}
function renderMomentum(){const rankedResults=ranked(),top=rankedResults.slice(0,3);document.querySelectorAll('[data-window]').forEach(el=>el.textContent=windowMinutes+'m');$('leader-title').textContent='Top 3 '+(direction==='long'?'Long':'Short')+'-Momentum';$('sort-label').textContent=direction==='long'?'Stärkster Anstieg zuerst ↑':'Stärkster Rückgang zuerst ↓';$('long').className=direction==='long'?'selected':'';$('short').className=direction==='short'?'selected':'';$('long').setAttribute('aria-pressed',direction==='long');$('short').setAttribute('aria-pressed',direction==='short');$('result-count').textContent=rankedResults.length+' Kontrakte';$('pairs').textContent=total||'—';$('coverage').textContent=`${scanned}/${total} geprüft · ${eligible} nach Volumenfilter`;
 const measured=results.filter(r=>Number.isFinite(r.returns[windowMinutes]));$('breadth').textContent=measured.length?num(measured.filter(r=>r.returns[windowMinutes]>0).length/measured.length*100,0)+'%':'—';const changes=measured.map(r=>r.returns[windowMinutes]).sort((a,b)=>a-b),m=Math.floor(changes.length/2),median=changes.length?(changes.length%2?changes[m]:(changes[m-1]+changes[m])/2):NaN;$('median').textContent=pct(median);$('median').className=tone(median);$('interval').textContent=target?interval(target):'—';
 $('leaders').innerHTML=top.length?top.map((r,i)=>`<article class="leader ${i===0?'first':''}"><div class="card-top"><a class="coin-identity" href="${url(r)}" target="_blank" rel="noopener noreferrer"><span class="coin-icon">${esc(r.base.slice(0,2))}</span><div><b>${esc(r.base)}</b><small>USDT PERP ↗</small></div></a><span class="rank">${direction==='long'?'↑ LONG':'↓ SHORT'} · 0${i+1}</span></div><div class="return ${tone(r.returns[windowMinutes])}">${pct(r.returns[windowMinutes])}</div><div class="return-label">${windowMinutes}m-Momentum · abgeschlossene Minuten</div><div class="card-spark">${spark(r.candles.map(c=>+c[4]),direction==='short'?'#f28183':COLORS[i])}</div><div class="card-bottom"><div>Letzter Preis¹<strong>${price(r.last)}</strong></div><div>Volumen-Puls · 5m<strong>${Number.isFinite(r.pulse)?num(r.pulse,1)+'×':'—'}</strong></div><div>Spread¹<strong>${Number.isFinite(r.spread)?num(r.spread,3)+'%':'—'}</strong></div></div><div class="futures-metrics"><span>Funding¹ <b>${Number.isFinite(r.funding)?num(r.funding,4)+'% / '+esc(r.fundInterval)+'h':'—'}</b></span><span>OI¹ <b>${compact(r.oi)} ${esc(r.base)}</b></span></div></article>`).join(''):`<div class="no-candidates">${busy?'Scan läuft.':'Keine passenden Kontrakte.'} ${direction==='long'?'Positive':'Negative'} ${windowMinutes}m-Renditen werden hier angezeigt.</div>`;
 if(top.length)chart();else{$('chart').className='chart-empty';$('chart').textContent='Keine passenden Kursverläufe.';$('legend').textContent='Top 3 · normierte Kursentwicklung'}
 const query=$('search').value.trim().toUpperCase(),filtered=rankedResults.filter(r=>r.symbol.includes(query));$('rows').innerHTML=filtered.slice(0,limit).map(r=>`<tr><td>${String(rankedResults.indexOf(r)+1).padStart(2,'0')}</td><td><a target="_blank" rel="noopener noreferrer" href="${url(r)}"><span class="coin-icon">${esc(r.base.slice(0,2))}</span><b>${esc(r.base)}</b><small>PERP ↗</small></a></td><td>${price(r.last)}</td>${[1,5,15].map(n=>`<td class="${tone(r.returns[n])}">${pct(r.returns[n])}</td>`).join('')}<td>${Number.isFinite(r.pulse)?num(r.pulse,1)+'×':'—'}</td><td>${Number.isFinite(r.spread)?num(r.spread,3)+'%':'—'}</td><td>${Number.isFinite(r.funding)?num(r.funding,4)+'% <small>/ '+esc(r.fundInterval)+'h</small>':'—'}</td><td>${compact(r.oi)}<small class="oi-unit">${esc(r.base)}</small></td><td>${compact(r.dayVolume)}</td><td>${spark(r.candles.map(c=>+c[4]),direction==='long'?COLORS[0]:'#f28183')}</td></tr>`).join('')||'<tr><td colspan="12" class="table-empty">Keine passenden Kontrakte im gewählten Scan-Universum.</td></tr>';$('more').hidden=filtered.length<=limit;}
const MOMENTUM_HEAD=$('table-head').innerHTML;
const SETUP_HEAD='<tr><th>#</th><th>Perpetual / USDT</th><th>Status</th><th>Impuls</th><th>Rücklauf</th><th>Gegenkerzen</th><th>Impulsvolumen³</th><th>Rücklaufvolumen³</th><th>Trigger</th><th>Strukturgrenze</th><th>Spread¹</th><th>Kerzenchart</th></tr>';
function setupLabel(s){return s.status==='confirmed'?'Fortsetzung bestätigt':'Rücksetzer läuft'}
function stateTag(s){return `<span class="setup-state ${s.status==='pullback'?'waiting':''}">${setupLabel(s)}</span>`}
function setupChart(){const list=ranked();let r=list.find(r=>r.symbol===selectedSymbol)||list[0];if(!r){$('chart-title').textContent='Setup im Kerzenchart';$('chart-period').textContent=patternOptions().minutes+'m-Kerzen';$('chart-footer').textContent='Geschlossene Kerzen · UTC';$('chart').className='chart-empty';$('chart').textContent='Kein passendes Setup. Regeln lockern oder nächsten Scan abwarten.';$('legend').textContent='Keine Treffer werden durch Momentum-Gewinner ersetzt.';$('setup-detail').innerHTML='';return}selectedSymbol=r.symbol;const s=getSetup(r),candles=s.candles,n=candles.length,levels=[s.trigger,s.invalidation,s.impulseExtreme,s.rangeLevel];let lo=Math.min(...candles.map(c=>c[3]),...levels),hi=Math.max(...candles.map(c=>c[2]),...levels);const pad=(hi-lo)*.14||1;hi+=pad;lo-=pad;const x=i=>62+(i+.5)*550/n,y=v=>28+(hi-v)/(hi-lo)*184,barWidth=Math.min(22,550/n*.6),indexOf=t=>candles.findIndex(c=>c[0]===t),band=(a,b,color)=>`<rect x="${62+a*550/n}" y="24" width="${Math.max(1,(b-a)*550/n)}" height="194" fill="${color}" opacity="0.08"/>`;
let svg='<svg viewBox="0 0 720 270" role="img" aria-label="'+esc(r.base)+' '+s.minutes+'-Minuten-Kerzen mit Impuls, Rücksetzer und Trigger">';svg+=band(indexOf(s.start),indexOf(s.pullbackStart),'#bbf96b')+band(indexOf(s.pullbackStart),indexOf(s.pullbackStart)+s.pullbackBars,'#e3c681');for(let i=0;i<4;i++){let v=lo+(hi-lo)*i/3;svg+=`<line x1="62" x2="612" y1="${y(v)}" y2="${y(v)}" stroke="#29373b" stroke-dasharray="3 5"/><text x="2" y="${y(v)+3}" fill="#7c9099" font-size="9">${price(v)}</text>`}
for(const [value,color,label]of [[s.trigger,'#e3c681','Trigger'],[s.invalidation,'#f28183','Struktur'],[s.rangeLevel,'#60d6c5','Range']])svg+=`<line x1="62" x2="612" y1="${y(value)}" y2="${y(value)}" stroke="${color}" stroke-width="1" stroke-dasharray="4 4"/><text x="620" y="${y(value)+3}" font-size="9" fill="${color}">${label}</text>`;
candles.forEach((c,i)=>{const color=c[4]>=c[1]?'#bbf96b':'#f28183';svg+=`<g><title>${time(c[0])} UTC · O ${price(c[1])} H ${price(c[2])} L ${price(c[3])} C ${price(c[4])}</title><line x1="${x(i)}" x2="${x(i)}" y1="${y(c[2])}" y2="${y(c[3])}" stroke="${color}"/><rect x="${x(i)-barWidth/2}" y="${Math.min(y(c[1]),y(c[4]))}" width="${barWidth}" height="${Math.max(1,Math.abs(y(c[1])-y(c[4])))}" fill="${color}" rx="1"/></g>`});[0,Math.floor(n/2),n-1].forEach(i=>svg+=`<text x="${x(i)}" y="241" text-anchor="middle" fill="#81959d" font-size="9">${time(candles[i][0])}</text>`);$('chart').className='pattern-chart';$('chart').innerHTML=svg+'</svg>';$('chart-title').textContent=r.base+' · '+(s.side==='long'?'Long':'Short')+'-Setup';$('chart-period').textContent=s.minutes+'m-Kerzen';$('legend').innerHTML='<span><i style="background:#bbf96b"></i>Impuls</span><span><i style="background:#e3c681"></i>Rücksetzer</span><span>'+setupLabel(s)+'</span>';$('chart-footer').textContent='Abgeschlossene Kerzen · UTC · Referenzmarken aus dem Muster, keine Orderausführung';
$('setup-detail').innerHTML=`<div>Trigger · letzte Gegenkerze<b>${price(s.trigger)} USDT</b></div><div>Strukturgrenze · Rücksetzertief/-hoch<b>${price(s.invalidation)} USDT</b></div><div>Impuls / Rücklauf<b>${pct(s.impulsePct)} / ${num(s.retracement*100,1)}%</b></div><div>Ausbruchsrange / Impulsextrem<b>${price(s.rangeLevel)} / ${price(s.impulseExtreme)} USDT</b></div><div class="detail-wide">${s.impulseBars} Impulskerzen + ${s.pullbackBars} Gegenkerzen${s.status==='confirmed'?' + 1 Bestätigungskerze':''} · ${s.setupMinutes} Minuten. ${s.side==='long'?'Ein Schlusskurs über dem Hoch':'Ein Schlusskurs unter dem Tief'} der letzten Gegenkerze gilt hier als Bestätigung.</div>`;
}
function chart(){if(mode==='setup')setupChart();else momentumChart()}
function renderSetups(){const candidates=ranked(),top=candidates.slice(0,3),opts=patternOptions();$('leader-title').textContent='Top 3 '+(direction==='long'?'Long':'Short')+'-Setups';$('sort-label').textContent='Bestätigt zuerst · danach Impulsvolumenfaktor';$('result-count').textContent=candidates.length+' Setups';$('pairs').textContent=total||'—';$('coverage').textContent=`${scanned}/${total} geprüft · ${eligible} nach Volumenfilter`;document.querySelectorAll('[data-window]').forEach(e=>e.textContent=windowMinutes+'m');const measured=results.filter(r=>Number.isFinite(r.returns[windowMinutes]));$('breadth').textContent=measured.length?num(measured.filter(r=>r.returns[windowMinutes]>0).length/measured.length*100,0)+'%':'—';const changes=measured.map(r=>r.returns[windowMinutes]).sort((a,b)=>a-b),m=Math.floor(changes.length/2),median=changes.length?(changes.length%2?changes[m]:(changes[m-1]+changes[m])/2):NaN;$('median').textContent=pct(median);$('median').className=tone(median);$('interval').textContent=target?interval(target):'—';
 if(!candidates.some(r=>r.symbol===selectedSymbol))selectedSymbol=top[0]?.symbol||'';
 $('leaders').innerHTML=top.length?top.map((r,i)=>{const s=getSetup(r);return `<article class="leader setup-card ${i===0?'first':''} ${selectedSymbol===r.symbol?'selected':''}"><div class="card-top"><a class="coin-identity" href="${url(r)}" target="_blank" rel="noopener noreferrer"><span class="coin-icon">${esc(r.base.slice(0,2))}</span><div><b>${esc(r.base)}</b><small>USDT PERP · ${s.minutes}m ↗</small></div></a><span class="rank">${direction==='long'?'↑ LONG':'↓ SHORT'} · 0${i+1}</span></div>${stateTag(s)}<div class="return ${tone(s.impulsePct)}">${pct(s.impulsePct)}</div><div class="return-label">Impuls über ${s.impulseBars} Kerzen · ${s.setupMinutes}m Gesamtsetup</div><div class="card-spark">${spark(s.candles.map(c=>c[4]),s.side==='long'?COLORS[i]:'#f28183')}</div><div class="card-bottom"><div>Rücklauf<strong>${num(s.retracement*100,1)}%</strong></div><div>Gegenkerzen<strong>${s.pullbackBars} × ${s.minutes}m</strong></div><div>Impulsvolumen³<strong>${num(s.volumeRatio,1)}×</strong></div></div><div class="futures-metrics"><span>Spread¹ <b>${Number.isFinite(r.spread)?num(r.spread,3)+'%':'—'}</b></span><span>Funding¹ <b>${Number.isFinite(r.funding)?num(r.funding,4)+'% / '+esc(r.fundInterval)+'h':'—'}</b></span><span>OI¹ <b>${compact(r.oi)} ${esc(r.base)}</b></span></div><button class="setup-action" data-setup-symbol="${esc(r.symbol)}">Setup ansehen ↗</button></article>`}).join(''):`<div class="no-candidates">${busy?'Scan läuft – bisher kein passendes Setup.':'Kein Setup erfüllt gerade deine Regeln.'} Gesucht: ${opts.pullbackBars} kleine Gegenkerzen nach einem volumenstarken Ausbruch. Die Liste bleibt leer, bis das Muster passt.</div>`;
 const query=$('search').value.trim().toUpperCase(),filtered=candidates.filter(r=>r.symbol.includes(query));$('rows').innerHTML=filtered.slice(0,limit).map(r=>{const s=getSetup(r);return `<tr><td>${String(candidates.indexOf(r)+1).padStart(2,'0')}</td><td><a href="${url(r)}" target="_blank" rel="noopener noreferrer"><b>${esc(r.base)}</b><small>PERP ↗</small></a></td><td>${stateTag(s)}</td><td class="${tone(s.impulsePct)}">${pct(s.impulsePct)}</td><td>${num(s.retracement*100,1)}%</td><td>${s.pullbackBars} × ${s.minutes}m</td><td>${num(s.volumeRatio,1)}×</td><td>${num(s.pullbackVolumeRatio,2)}×</td><td>${price(s.trigger)}</td><td>${price(s.invalidation)}</td><td>${Number.isFinite(r.spread)?num(r.spread,3)+'%':'—'}</td><td><button class="setup-table-button" data-setup-symbol="${esc(r.symbol)}">Setup ansehen</button></td></tr>`}).join('')||'<tr><td colspan="12" class="table-empty">Keine passenden Setups für Richtung, Regeln und Scan-Universum.</td></tr>';$('more').hidden=filtered.length<=limit;setupChart();
}
function render(){document.body.classList.toggle('tradfi-mode',mode==='tradfi');$('tradfi-view').hidden=mode!=='tradfi';document.body.classList.toggle('breakout-mode',mode==='breakout');document.body.classList.toggle('strict-profile',mode==='breakout'&&$('breakout-profile').value==='candles');$('breakout-view').hidden=mode!=='breakout';if(mode==='tradfi'){renderTradfi();return}if(mode==='breakout')$('strategy').hidden=$('breakout-profile').value!=='candles';if(mode==='breakout'){['long','short'].forEach(d=>{$(d).className=direction===d?'selected':'';$(d).setAttribute('aria-pressed',direction===d)});renderBreakout();return}const setupMode=mode==='setup';$('strategy').hidden=!setupMode;$('setup-detail').hidden=!setupMode;$('timeframe').disabled=setupMode;$('table-head').innerHTML=setupMode?SETUP_HEAD:MOMENTUM_HEAD;$('ranking-title').textContent=setupMode?'Setup-Kandidaten':'Momentum-Ranking';$('table-note').textContent=setupMode?'¹ Ticker-Snapshot beim Scanstart. ³ Impulsvolumen = Ø USDT-Volumen je Impulskerze / Ø der zehn vorherigen Kerzen; Rücklaufvolumen = Ø je Gegenkerze / Ø je Impulskerze. Trigger und Strukturgrenze sind Musterreferenzen.':'¹ Ticker-Snapshot beim Scanstart; OI in Basis-Token. ² Quotenvolumen letzte 5m / vorherige 5m. Ranking ohne Hebel.';const opts=patternOptions();$('strategy-summary').textContent=`${opts.minutes}m-Kerzen · ${opts.pullbackBars} kleine Gegenkerzen · Impuls ≥ ${num(opts.minImpulse,1)}% · Impulsvolumen ≥ ${num(opts.minVolume,1)}× · Rücklauf 5–${num(opts.maxRetracement*100,0)}%${opts.requireQuiet?' · sinkendes Rücksetzer-Volumen':''}. ${opts.minutes===1?'Typische Musterdauer: '+(2+opts.pullbackBars)+'–'+(7+opts.pullbackBars)+' Minuten.':opts.pullbackBars+' × 5m-Gegenkerzen dauern '+(opts.pullbackBars*5)+' Minuten; das Gesamtsetup dauert länger.'}`;['long','short'].forEach(d=>{$(d).className=direction===d?'selected':'';$(d).setAttribute('aria-pressed',direction===d)});if(setupMode)renderSetups();else{$('chart-title').textContent='Der Weg an die Spitze';$('chart-period').textContent='60 Minuten';$('chart-footer').textContent='Rendite relativ zum ersten gemeinsamen Schlusskurs · 1m-Kerzen · UTC';renderMomentum()}}

function renderHistory(){$('history-list').innerHTML=history.length?history.slice(0,12).map(h=>`<div class="history-row"><b>${esc(new Date(h.target).toLocaleDateString('de-DE',{timeZone:'UTC'}))} · ${time(h.target)} UTC · ${h.mode==='setup'?'Setup '+h.rules.minutes+'m':'Momentum '+h.window+'m'}</b><span>${h.count}/${h.total} Kontrakte · ${h.scope?'Top '+h.scope:'Alle'} · ${h.direction==='long'?'Long':'Short'}${h.failures?' · unvollständig':''}</span><span>${h.top.map(r=>esc(r.base)+' '+pct(r.change)+(r.status?' · '+(r.status==='confirmed'?'bestätigt':'Rücksetzer'):'')).join('　/　')||'Keine passenden Setups'}</span></div>`).join(''):'Abgeschlossene Scans werden lokal gespeichert. Frühere Momentum- und Spot-Historien bleiben separat im Browser erhalten.';}
function saveHistory(){if(mode==='breakout'||mode==='tradfi'||!results.length)return;const minimum=+$('volume').value,scope=+$('universe').value;const entry={target,window:windowMinutes,mode,statusFilter:$('setup-status').value,rules:patternOptions(),direction,count:results.length,total,filter:minimum,scope,failures,top:ranked().slice(0,3).map(r=>{const s=mode==='setup'?getSetup(r):null;return {base:r.base,change:s?s.impulsePct:r.returns[windowMinutes],status:s?.status||'',retracement:s?.retracement??null,volumeRatio:s?.volumeRatio??null,trigger:s?.trigger??null,invalidation:s?.invalidation??null}})};history=history.filter(h=>!(h.target===target&&h.mode===mode&&h.statusFilter===entry.statusFilter&&h.window===windowMinutes&&h.direction===direction&&h.filter===minimum&&h.scope===scope&&JSON.stringify(h.rules)===JSON.stringify(entry.rules)));history.unshift(entry);history=history.slice(0,180);try{localStorage.setItem('pulse-breakout-history-v1',JSON.stringify(history))}catch{}renderHistory()}
function controls(disabled){['refresh','volume','universe','mode'].forEach(id=>$(id).disabled=disabled)}
async function scan(){if(busy)return;busy=true;lastAttempt=Date.now();controls(true);$('connection').textContent='● Futures-Scan läuft';$('notice').className='notice';$('notice').textContent='Lade handelbare USDT-Perpetuals. Das Universum wird nach 24h-Volumen gewählt.';$('progress').style.width='0%';
 try{const [tickers,contracts,instruments]=await Promise.all([api('mix/market/tickers?productType=USDT-FUTURES'),api('mix/market/contracts?productType=USDT-FUTURES'),mode==='tradfi'?api('market/instruments?category=USDT-FUTURES',1,'https://api.bitget.com/api/v3/'):Promise.resolve(null)]);const stockSymbols=mode==='tradfi'?new Set(instruments.filter(s=>String(s.isRwa).toUpperCase()==='YES'&&String(s.instrumentType).toLowerCase()==='stock'&&s.status==='online').map(s=>s.symbol)):null;const allowed=new Map(contracts.filter(s=>s.symbolStatus==='normal'&&s.symbolType==='perpetual'&&s.quoteCoin==='USDT'&&(!stockSymbols||stockSymbols.has(s.symbol))).map(s=>[s.symbol,s]));snapshot=Date.now();const minimum=+$('volume').value,scope=+$('universe').value;let candidates=tickers.filter(t=>allowed.has(t.symbol)&&numeric(t.quoteVolume)>=minimum).sort((a,b)=>numeric(b.quoteVolume)-numeric(a.quoteVolume));eligible=candidates.length;if(scope)candidates=candidates.slice(0,scope);target=Math.floor(snapshot/MINUTE)*MINUTE;results=[];scanned=0;failures=0;total=candidates.length;render();let index=0;
 async function worker(){while(index<candidates.length){const t=candidates[index++];try{const data=await api('mix/market/candles?symbol='+encodeURIComponent(t.symbol)+'&productType=USDT-FUTURES&granularity=1m&limit=185&endTime='+(target-1));const candles=data.filter(c=>+c[0]<target&&+c[0]>=target-180*MINUTE&&+c[1]>0&&+c[4]>0).sort((a,b)=>+a[0]-+b[0]);const windows=Object.fromEntries([1,5,15].map(n=>[n,windowData(candles,target,n)]));if(!windows[1])throw Error('Keine abgeschlossene Minute');const prev=windowData(candles,target-5*MINUTE,5);const row={symbol:t.symbol,base:allowed.get(t.symbol).baseCoin,...metrics(t,allowed.get(t.symbol)),returns:Object.fromEntries([1,5,15].map(n=>[n,windows[n]?.change??NaN])),pulse:prev?.volume>0&&windows[5]?windows[5].volume/prev.volume:NaN,candles};row.setups=PulsePattern.detect(candles,target,patternOptions());results.push(row)}catch{failures++}scanned++;$('progress').style.width=(scanned/total*100)+'%';$('notice').textContent=`Vorläufig: ${scanned}/${total} Kontrakte geprüft · ${failures} fehlen · ${scope?'Top '+scope+' nach 24h-Volumen':'Alle nach Volumenfilter'} · Stand ${time(target)} UTC.`;if(scanned%8===0||scanned===total)render()}}
 await Promise.all(Array.from({length:8},()=>worker()));render();if(!results.length)throw Error(total?'Keine passenden abgeschlossenen Futures-Kerzen.':'Keine Kontrakte erfüllen den Filter.');$('updated').textContent='Scan beendet · '+time(Date.now())+' UTC';const stale=Date.now()-target>90000;$('connection').textContent=stale?'● Scan-Zeitfenster veraltet':failures?'● Teilweise verfügbar':'● Futures verbunden';$('notice').textContent=`${failures?'Unvollständiger Scan':'Scan abgeschlossen'}: ${results.length}/${total} Kontrakte · ${eligible} erfüllen den Volumenfilter · Momentum bis ${time(target)} UTC · Ticker-Snapshot ${time(snapshot)} UTC.${stale?' Großer Scan dauert länger als eine Minute. Für kurze Zyklen das Universum reduzieren.':''}`;saveHistory();
 }catch(e){$('notice').className='notice error';$('notice').textContent='Futures-Daten nicht verfügbar: '+e.message+' Sichtbare Daten können veraltet sein. Erneut scannen.';$('connection').textContent='● Daten eingeschränkt'}finally{busy=false;controls(false);render()}}
$('refresh').addEventListener('click',scan);['volume','universe'].forEach(id=>$(id).addEventListener('change',scan));$('timeframe').addEventListener('change',()=>{windowMinutes=+$('timeframe').value;render();if(!busy)saveHistory()});['long','short'].forEach(d=>$(d).addEventListener('click',()=>{direction=d;limit=20;render();if(!busy)saveHistory()}));$('search').addEventListener('input',()=>{limit=20;render()});$('more').addEventListener('click',()=>{limit+=30;render()});$('export').addEventListener('click',()=>{if(!history.length){$('notice').textContent='Nach dem ersten abgeschlossenen Scan steht der Export bereit.';return}const header=['Zeit UTC','Modus','Statusfilter','Richtung','Momentum Minuten','Setup Kerzen Minuten','Gegenkerzen','Min Impuls Prozent','Min Volumenfaktor','Max Ruecklauf','Leiser Ruecksetzer','Universum Top N (0=alle)','Volumenfilter USDT','Ausgewertet','Im Scan','Fehlend','Rang','Token','Rendite oder Impuls Prozent','Setup Status','Ruecklauf Anteil','Impulsvolumenfaktor','Trigger','Strukturgrenze'];const rows=history.flatMap(h=>(h.top.length?h.top:[{}]).map((r,i)=>[new Date(h.target).toISOString(),h.mode,h.statusFilter,h.direction,h.window,h.rules.minutes,h.rules.pullbackBars,h.rules.minImpulse,h.rules.minVolume,h.rules.maxRetracement,h.rules.requireQuiet,h.scope,h.filter,h.count,h.total,h.failures,r.base?i+1:'',r.base||'',r.change??'',r.status||'',r.retracement??'',r.volumeRatio??'',r.trigger??'',r.invalidation??'']));const csv='\uFEFF'+[header,...rows].map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n');const link=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=link;a.download='bitget-breakout-setups.csv';a.click();setTimeout(()=>URL.revokeObjectURL(link),1000)});

setInterval(()=>{const remaining=MINUTE-Date.now()%MINUTE;$('countdown').textContent='00:'+String(Math.floor(remaining/1000)).padStart(2,'0');if(!busy&&Date.now()%MINUTE>=3000&&target<Math.floor(Date.now()/MINUTE)*MINUTE&&Date.now()-lastAttempt>15000)scan();if(!busy&&target&&Date.now()-target>90000)$('connection').textContent='● Daten veraltet'},1000);
['tradfi-status','tradfi-change','tradfi-impulse'].forEach(id=>$(id).addEventListener('change',render));$('tradfi-search').addEventListener('input',render);
['breakout-profile','breakout-status','breakout-volume'].forEach(id=>$(id).addEventListener('change',render));$('breakout-search').addEventListener('input',render);$('breakout-list').addEventListener('click',event=>{const button=event.target.closest('[data-detail]');if(!button)return;mode='setup';$('mode').value='setup';$('setup-status').value='all';selectedSymbol=button.dataset.detail;render();$('chart').scrollIntoView({behavior:'smooth',block:'center'})});
$('mode').addEventListener('change',()=>{const previous=mode;mode=$('mode').value;selectedSymbol='';limit=20;if((previous==='tradfi')!==(mode==='tradfi')){results=[];total=0;scanned=0;eligible=0;target=0;render();scan()}else{render();if(!busy)saveHistory()}});
['candle-size','pullback-count','impulse-min','impulse-volume','max-retrace','quiet-pullback'].forEach(id=>$(id).addEventListener('change',()=>{recomputePatterns();selectedSymbol='';render();if(!busy)saveHistory()}));
